import pty, os, subprocess, time, select, shutil

def test_init_seq(inputs, cwd="/tmp/test_init_seq"):
    os.makedirs(cwd, exist_ok=True)
    for f in os.listdir(cwd):
        p=os.path.join(cwd,f)
        if os.path.isdir(p):
            shutil.rmtree(p)
        else:
            os.remove(p)
    master, slave = pty.openpty()
    proc = subprocess.Popen(['/workspace/executable', 'init'], cwd=cwd, stdin=slave, stdout=slave, stderr=slave, text=False, close_fds=True)
    os.close(slave)
    time.sleep(0.4)
    def read(timeout=0.7):
        rlist,_,_ = select.select([master],[],[],timeout)
        if rlist:
            try:
                return os.read(master, 8192)
            except:
                return b''
        return b''
    data = read(1)
    print("PROMPT0:", repr(data.decode(errors='ignore')[:1000]))
    for inp in inputs:
        print(f"-> sending {repr(inp)}")
        os.write(master, (inp+"\n").encode())
        time.sleep(0.4)
        data = read(0.8)
        print(f"RECV:", repr(data.decode(errors='ignore')[:1500]))
        # collect additional
        for i in range(3):
            d=read(0.3)
            if not d:
                break
            print(f"CONT {i}:", repr(d.decode(errors='ignore')[:1000]))
    # wait
    time.sleep(0.8)
    for i in range(6):
        d=read(0.5)
        if not d:
            break
        print(f"TAIL {i}:", repr(d.decode(errors='ignore')[:2000]))
    try:
        proc.wait(timeout=2)
        print("exit", proc.returncode)
    except:
        proc.kill()
        print("killed")
        try:
            proc.wait(timeout=1)
            print("exit after kill", proc.returncode)
        except: pass
    os.close(master)
    print("files:", os.listdir(cwd))
    for f in os.listdir(cwd):
        fp=os.path.join(cwd,f)
        if os.path.isfile(fp):
            print(f"--- {f} ---")
            try:
                print(open(fp).read()[:4000])
            except: pass
        elif os.path.isdir(fp):
            print(f"--- dir {f} ---")
            for sub in os.listdir(fp)[:10]:
                print(sub)

